#!/usr/bin/env python3
"""Minimal dependency-free parquet reader for simple byte-array/bool columns.
Supports: snappy / uncompressed codecs, PLAIN and RLE_DICTIONARY encodings for
BYTE_ARRAY columns, PLAIN for BOOLEAN. Enough to inspect small datasets."""
import struct, sys, json

# ---------------- snappy ----------------
def snappy_decompress(buf):
    pos = 0
    # varint uncompressed length
    length = 0; shift = 0
    while True:
        b = buf[pos]; pos += 1
        length |= (b & 0x7F) << shift
        if not (b & 0x80): break
        shift += 7
    out = bytearray()
    while pos < len(buf):
        tag = buf[pos]; pos += 1
        t = tag & 3
        if t == 0:  # literal
            ln = tag >> 2
            if ln < 60:
                ln += 1
            else:
                nb = ln - 59
                ln = int.from_bytes(buf[pos:pos+nb], 'little') + 1
                pos += nb
            out += buf[pos:pos+ln]; pos += ln
        else:
            if t == 1:
                ln = ((tag >> 2) & 7) + 4
                off = ((tag >> 5) << 8) | buf[pos]; pos += 1
            elif t == 2:
                ln = (tag >> 2) + 1
                off = int.from_bytes(buf[pos:pos+2], 'little'); pos += 2
            else:
                ln = (tag >> 2) + 1
                off = int.from_bytes(buf[pos:pos+4], 'little'); pos += 4
            start = len(out) - off
            for i in range(ln):
                out.append(out[start + i])
    assert len(out) == length, (len(out), length)
    return bytes(out)

# ---------------- thrift compact ----------------
class TReader:
    def __init__(self, data, pos=0):
        self.d = data; self.p = pos
    def byte(self):
        b = self.d[self.p]; self.p += 1; return b
    def varint(self):
        r = 0; s = 0
        while True:
            b = self.byte(); r |= (b & 0x7F) << s
            if not (b & 0x80): return r
            s += 7
    def zigzag(self):
        n = self.varint(); return (n >> 1) ^ -(n & 1)
    def read_value(self, ctype):
        if ctype == 1: return True
        if ctype == 2: return False
        if ctype == 3: return struct.unpack('b', bytes([self.byte()]))[0]
        if ctype in (4, 5, 6): return self.zigzag()
        if ctype == 7:
            v = struct.unpack('<d', self.d[self.p:self.p+8])[0]; self.p += 8; return v
        if ctype == 8:
            ln = self.varint(); v = self.d[self.p:self.p+ln]; self.p += ln
            try: return v.decode('utf-8')
            except UnicodeDecodeError: return v
        if ctype in (9, 10):
            h = self.byte(); size = h >> 4; et = h & 0x0F
            if size == 15: size = self.varint()
            return [self.read_value(et) for _ in range(size)]
        if ctype == 11:
            size = self.varint()
            if size == 0: return {}
            kt = self.byte(); kty = kt >> 4; vty = kt & 0x0F
            return {self.read_value(kty): self.read_value(vty) for _ in range(size)}
        if ctype == 12: return self.read_struct()
        raise ValueError(f'unknown ctype {ctype}')
    def read_struct(self):
        res = {}; last = 0
        while True:
            h = self.byte()
            if h == 0: return res
            delta = h >> 4; ctype = h & 0x0F
            if delta: fid = last + delta
            else: fid = self.zigzag()
            last = fid
            res[fid] = self.read_value(ctype)

# ---------------- parquet ----------------
def read_footer(data):
    assert data[-4:] == b'PAR1'
    flen = struct.unpack('<I', data[-8:-4])[0]
    fm = TReader(data[len(data)-8-flen:len(data)-8]).read_struct()
    return fm

def read_pages(data, cc_meta):
    # ColumnMetaData fields: 1 type,2 encodings,3 path,4 codec,5 num_values,
    # 6 total_uncompressed,7 total_compressed,9 data_page_offset,10 index_page_offset,11 dict_page_offset
    codec = cc_meta[4]
    total = cc_meta[7]
    start = min(x for x in [cc_meta.get(9), cc_meta.get(11)] if x is not None)
    pos = start; end = start + total
    pages = []
    while pos < end:
        r = TReader(data, pos); ph = r.read_struct(); pos = r.p
        # PageHeader: 1 type, 2 uncompressed_size, 3 compressed_size, 5 data_page_header, 7 dict_page_header, 8 data_page_header_v2
        comp = data[pos:pos+ph[3]]; pos += ph[3]
        if codec == 1: raw = snappy_decompress(comp)
        elif codec == 0: raw = comp
        else: raise ValueError(f'codec {codec} unsupported')
        pages.append((ph, raw))
    return pages

def decode_plain_byte_array(raw, n):
    out = []; p = 0
    while len(out) < n and p < len(raw):
        ln = struct.unpack('<I', raw[p:p+4])[0]; p += 4
        out.append(raw[p:p+ln]); p += ln
    return out

def decode_rle_bitpacked(raw, bit_width, n):
    """RLE/bit-packed hybrid, with 4-byte length prefix (as used in data pages for dict indices w/o prefix? no)."""
    out = []; r = TReader(raw)
    while len(out) < n and r.p < len(raw):
        header = r.varint()
        if header & 1:  # bit packed
            groups = header >> 1; cnt = groups * 8
            nbytes = (cnt * bit_width + 7) // 8
            chunk = raw[r.p:r.p+nbytes]; r.p += nbytes
            val = int.from_bytes(chunk, 'little')
            for i in range(cnt):
                out.append((val >> (i * bit_width)) & ((1 << bit_width) - 1))
        else:
            cnt = header >> 1
            nb = (bit_width + 7) // 8
            v = int.from_bytes(raw[r.p:r.p+nb], 'little'); r.p += nb
            out.extend([v] * cnt)
    return out[:n]

def read_column(data, cc_meta, max_def_level, max_rep_level):
    ptype = cc_meta[1]
    pages = read_pages(data, cc_meta)
    dictionary = None
    values = []; def_levels = []; rep_levels = []
    for ph, raw in pages:
        if ph[1] == 2:  # dictionary page
            dph = ph[7]; nvals = dph[1]
            if ptype == 6: dictionary = decode_plain_byte_array(raw, nvals)
            elif ptype == 0: dictionary = [bool(b) for b in raw[:nvals]]
            else: raise ValueError('dict for type %d' % ptype)
            continue
        if ph[1] == 0:
            dph = ph[5]; nvals = dph[1]; enc = dph[2]
            p = 0
            if max_rep_level > 0:
                ln = struct.unpack('<I', raw[p:p+4])[0]; p += 4
                bw = (max_rep_level).bit_length()
                rep_levels += decode_rle_bitpacked(raw[p:p+ln], bw, nvals); p += ln
            else:
                rep_levels += [0]*nvals
            if max_def_level > 0:
                ln = struct.unpack('<I', raw[p:p+4])[0]; p += 4
                bw = (max_def_level).bit_length()
                dl = decode_rle_bitpacked(raw[p:p+ln], bw, nvals); p += ln
            else:
                dl = [0]*nvals
            def_levels += dl
            nnon = sum(1 for x in dl if x == max_def_level)
            body = raw[p:]
            if enc in (2, 8):  # PLAIN_DICTIONARY / RLE_DICTIONARY
                bw = body[0]; idx = decode_rle_bitpacked(body[1:], bw, nnon)
                vals = [dictionary[i] for i in idx]
            elif enc == 0:
                if ptype == 6: vals = decode_plain_byte_array(body, nnon)
                elif ptype == 0:
                    vals = []
                    for i in range(nnon):
                        vals.append(bool((body[i//8] >> (i % 8)) & 1))
                else: raise ValueError('plain type %d' % ptype)
            else:
                raise ValueError(f'encoding {enc}')
            values += vals
        elif ph[1] == 3:
            dph = ph[8]; nvals = dph[1]; nnulls = dph[2]; nrows = dph[3]; enc = dph[4]
            dl_len = dph[5]; rl_len = dph[6]
            p = 0
            if max_rep_level > 0:
                bw = (max_rep_level).bit_length()
                rep_levels += decode_rle_bitpacked(raw[p:p+rl_len], bw, nvals)
            else:
                rep_levels += [0]*nvals
            p += rl_len
            if max_def_level > 0:
                bw = (max_def_level).bit_length()
                dl = decode_rle_bitpacked(raw[p:p+dl_len], bw, nvals)
            else:
                dl = [0]*nvals
            p += dl_len
            def_levels += dl
            nnon = sum(1 for x in dl if x == max_def_level)
            body = raw[p:]
            if enc in (2, 8):
                bw = body[0]; idx = decode_rle_bitpacked(body[1:], bw, nnon)
                vals = [dictionary[i] for i in idx]
            elif enc == 0:
                if ptype == 6: vals = decode_plain_byte_array(body, nnon)
                elif ptype == 0:
                    vals = [bool((body[i//8] >> (i % 8)) & 1) for i in range(nnon)]
                else: raise ValueError('plain type %d' % ptype)
            else: raise ValueError(f'encoding {enc}')
            values += vals
    return values, def_levels, rep_levels

def schema_levels(schema):
    """Compute max def/rep levels for each leaf column path."""
    # schema: list of SchemaElement {1 type,2 type_length,3 repetition_type,4 name,5 num_children,...}
    leaves = []
    def walk(i, path, dl, rl):
        el = schema[i]
        name = el.get(4); rep = el.get(3); nch = el.get(5, 0)
        if i != 0:
            if rep == 1: dl += 1       # OPTIONAL
            elif rep == 2: dl += 1; rl += 1  # REPEATED
            path = path + [name]
        j = i + 1
        if nch == 0 and i != 0:
            leaves.append((path, dl, rl, el.get(1)))
            return j
        for _ in range(nch):
            j = walk(j, path, dl, rl)
        return j
    walk(0, [], 0, 0)
    return leaves

def read_parquet(path):
    data = open(path, 'rb').read()
    fm = read_footer(data)
    schema = fm[2]; nrows = fm[3]; rgs = fm[4]
    leaves = schema_levels(schema)
    cols = {}
    for rg in rgs:
        for cc in rg[1]:
            md = cc[3]
            pth = md[3]
            key = '.'.join(pth)
            leaf = next(l for l in leaves if '.'.join(l[0]) == key)
            vals, dls, rls = read_column(data, md, leaf[1], leaf[2])
            cols.setdefault(key, {'values': [], 'def': [], 'rep': [], 'maxdef': leaf[1], 'maxrep': leaf[2]})
            cols[key]['values'] += vals; cols[key]['def'] += dls; cols[key]['rep'] += rls
    return nrows, cols, fm

def assemble_rows(nrows, cols):
    """Assemble leaf columns into per-row python values (handles one level of list-of-struct)."""
    rows = [dict() for _ in range(nrows)]
    for key, c in cols.items():
        vals = c['values']; dls = c['def']; rls = c['rep']; md = c['maxdef']; mr = c['maxrep']
        vi = 0; row = -1
        for i, (d, r) in enumerate(zip(dls, rls)):
            if r == 0: row += 1
            if d == md:
                v = vals[vi]; vi += 1
                if isinstance(v, bytes):
                    try: v = v.decode('utf-8')
                    except UnicodeDecodeError: pass
            else:
                v = None
                if mr > 0 and d == 0:
                    rows[row].setdefault(key, []); continue
            if mr > 0:
                rows[row].setdefault(key, []).append(v)
            else:
                rows[row][key] = v
    return rows

if __name__ == '__main__':
    path = sys.argv[1]
    nrows, cols, fm = read_parquet(path)
    rows = assemble_rows(nrows, cols)
    print(json.dumps({'nrows': nrows, 'columns': list(cols.keys())}, indent=1))
    limit = int(sys.argv[2]) if len(sys.argv) > 2 else 3
    for i, r in enumerate(rows[:limit]):
        print(f'--- row {i} ---')
        for k, v in r.items():
            s = json.dumps(v, ensure_ascii=False)
            print(f'  {k}: {s[:700]}')

